using System.Security.Claims;using LocalPro.Web.Data;using LocalPro.Web.Services;using Microsoft.AspNetCore.Authorization;using Microsoft.AspNetCore.Mvc;using Microsoft.AspNetCore.Mvc.RazorPages;using Microsoft.EntityFrameworkCore;
namespace LocalPro.Web.Pages.Professional;
[Authorize]public class EditModel(AppDbContext db):PageModel{
 [BindProperty]public ProfessionalInput Input{get;set;}=new("",1,"Mogadishu","","","",20,1,8,18,true);public List<Domain.Category> Categories{get;set;}=[];public bool? Approved{get;set;}
 public async Task OnGetAsync(){Categories=await db.Categories.ToListAsync();var p=await db.Professionals.SingleOrDefaultAsync(x=>x.UserId==User.FindFirstValue(ClaimTypes.NameIdentifier));if(p!=null){Approved=p.Approved;Input=new(p.Name,p.CategoryId,p.City,p.Neighborhood,p.Bio,p.Phone,p.HourlyRate,p.YearsExperience,p.StartHour,p.EndHour,p.AcceptingRequests);}}
 public async Task<IActionResult> OnPostAsync(){Categories=await db.Categories.ToListAsync();var error=ProfessionalInput.Validate(Input);if(error!=null)ModelState.AddModelError("",error);if(!Categories.Any(c=>c.Id==Input.CategoryId))ModelState.AddModelError("","Choose a service category.");if(!ModelState.IsValid)return Page();var id=User.FindFirstValue(ClaimTypes.NameIdentifier)!;var p=await db.Professionals.SingleOrDefaultAsync(x=>x.UserId==id);if(p==null){p=new(){UserId=id};db.Add(p);}Input.Apply(p);await db.SaveChangesAsync();TempData["Success"]="Your profile has been submitted for approval. Changes to approved profiles require another review.";return RedirectToPage();}}
